 const tables:Record<string,any[]>=JSON.parse(localStorage.getItem('product-workbook-fixture')??'null')??initial;next+=tables.products.length;
 const calls:{name:string;args:any}[]=[];
 const create=(a:any,sku:string,name:string,barcode:string|null=null,parent:string|null=null,flavor:string|null=null)=>{const row={id:uid(),sku:sku.toUpperCase(),barcode,name_ar:name,description:a.p_description??null,category_id:a.p_category_id??'cat',brand_id:a.p_brand_id??null,unit_id:a.p_unit_id??'pkt',purchase_unit_id:a.p_purchase_unit_id??'ctn',units_per_purchase_unit:String(a.p_units_per_purchase_unit??12),default_purchase_price_in_minor_units:String(a.p_default_purchase_price_in_minor_units??6000),sale_unit_id:a.p_sale_unit_id??'ctn',units_per_sale_unit:String(a.p_units_per_sale_unit??12),default_sale_price_in_minor_units:String(a.p_default_sale_price_in_minor_units??9000),cost_price_in_minor_units:String(a.p_cost_price_in_minor_units??500),min_stock_level:String(a.p_min_stock_level??0),max_stock_level:a.p_max_stock_level??null,is_active:true,parcel_only:a.p_parcel_only??false,updated_at:String(++version),flavor_master_product_id:parent,is_flavor_master:false,flavor_name_ar:flavor};tables.products.push(row);return row;};
 const client={auth:{getUser:async()=>({data:{user:{id:actor}},error:null})},from:(table:string)=>{const filters:((r:any)=>boolean)[]=[];let single=false,lo=0,hi=Infinity;
 const run=()=>{const rows=tables[table].filter(r=>filters.every(f=>f(r))).slice(lo,hi+1);return{data:single?rows[0]:rows,error:null};};
 const query:any={select:()=>query,order:()=>query,range:(a:number,b:number)=>{lo=a;hi=b;return query;},eq:(key:string,value:any)=>{filters.push(r=>r[key]===value);return query;},limit:(n:number)=>{hi=n-1;return query;},single:()=>{single=true;return query;},then:(resolve:any)=>Promise.resolve(run()).then(resolve)};return query;},rpc:async(name:string,a:any)=>{calls.push({name,args:structuredClone(a)});
 if(name==='get_go_live_setup_status_v1')return {data:{finished:finished(),products:{},stock:{},customers:{},suppliers:{}},error:null};
 if(name==='create_product_family_with_flavors_v2'){const parent=create(a,a.p_sku,a.p_name_ar);parent.is_flavor_master=true;for(const f of a.p_flavors)create(a,a.p_sku+'-F-'+next,a.p_name_ar+' - '+f.nameAr,null,parent.id,f.nameAr);if(loseCreate){loseCreate=false;return{data:null,error:{message:'LOCAL_LOST_RESPONSE'}};}return{data:{success:true,productId:parent.id},error:null};}
 if(name==='import_go_live_products_v1'){for(const p of a.p_rows)create({p_units_per_purchase_unit:p.units_per_purchase_unit,p_units_per_sale_unit:p.units_per_sale_unit,p_default_purchase_price_in_minor_units:p.purchase_package_price_in_minor_units,p_default_sale_price_in_minor_units:p.sale_package_price_in_minor_units,p_cost_price_in_minor_units:p.cost_per_base_unit_in_minor_units,p_min_stock_level:p.min_stock_level,p_parcel_only:p.parcel_only},p.sku,p.name_ar,p.barcode||null);return{data:{success:true},error:null};}
 if(name==='update_product_flavor_v2'){const row=tables.products.find(p=>p.id===a.p_flavor_product_id);if(row.updated_at!==a.p_expected_updated_at)throw Error('LOCAL_CAS_CONFLICT');row.barcode=a.p_barcode;row.updated_at=String(++version);if(loseWrite){loseWrite=false;return{data:null,error:{message:'RAW TOKEN'}};}return{data:{success:true},error:null};}
 if(name==='update_product_master_v5'){const row=tables.products.find(p=>p.id===a.p_product_id);if(row.updated_at!==a.p_expected_updated_at)throw Error('LOCAL_CAS_CONFLICT');if(row.flavor_master_product_id&&a.p_parcel_only!==null)throw Error('LOCAL_INHERITED_METHOD');for(const[key,value]of Object.entries(a))if(!['p_product_id','p_expected_updated_at','p_image_url'].includes(key)&&!(key==='p_parcel_only'&&value===null))row[key.slice(2)]=value;row.updated_at=String(++version);if(loseWrite&&row.flavor_master_product_id){loseWrite=false;return{data:null,error:{message:'RAW'}};}return{data:{success:true},error:null};}throw Error('UNEXPECTED_RPC');}};
 const rpc=client.rpc;client.rpc=async(name,a)=>{try{const result=await rpc(name,a);if(name==='create_product_family_with_flavors_v2'&&holdCreate){holdCreate=false;await new Promise<void>(resolve=>releaseCreate=resolve);}return result;}finally{localStorage.setItem('product-workbook-fixture',JSON.stringify(tables));}};
 return{client,tables,calls,holdCreate:()=>{holdCreate=true;},releaseCreate:()=>releaseCreate?.(),loseCreate:()=>{loseCreate=true;},loseWrite:()=>{loseWrite=true;}};
}

