import { supabase, isSupabaseConfigured } from '../../lib/supabase';
import { Product } from '../../types';
import { businessErrorMessage } from '../../utils/businessError';
import {
  PRODUCT_EDIT_CONFLICT_MESSAGE,
  readProductEditSnapshot,
  type ProductEditSnapshot,
} from '../../utils/productEditConflict';

export interface CreateProductInput {
  parcelOnly?: boolean;
  sku: string;
  barcode?: string;
  nameAr: string;
  description?: string;
  categoryId?: string;
  brandId?: string;
  unitId?: string;
  unitName?: string;
  purchasePackage?: string;
  unitsPerPackage?: number;
  defaultPurchasePrice?: number;
  salePackage?: string;
  unitsPerSalePackage: number;
  salePackagePrice: number;
  costPrice: number; // in JOD
  reorderLevel?: number;
  maxStockLevel?: number;
  warehouseId?: string;
  branchId?: string;
  openingQuantity: number;
  imageUrl?: string;
}

export interface SupabaseFetchError {
  message: string;
  code?: string;
  status?: number | string;
  details?: string;
  hint?: string;
}

export interface SupabaseRpcResult {
  success: boolean;
  productId?: string;
  message?: string;
  error?: string;
  errorDetails?: {
    code?: string;
    message: string;
    details?: string;
    hint?: string;
    status?: number | string;
  };
  /** Present when the save was refused because the product changed since it was opened (migration 170). */
  conflict?: ProductEditSnapshot;
  /** products.updated_at after a successful versioned save. */
  updatedAt?: string;
}

function readErrorStatus(error: unknown): number | string | undefined {
  if (!error || typeof error !== 'object' || !('status' in error)) {
    return undefined;
  }

  const status = (error as { status?: unknown }).status;
  return typeof status === 'number' || typeof status === 'string'
    ? status
    : undefined;
}

type ProductMutationError = {
  message?: string;
  code?: string;
  details?: string;
  hint?: string;
  constraint?: string;
};

export function toProductMutationFailure(
  error: unknown,
  fallbackMessage: string
): SupabaseRpcResult {
  const source =
    error && typeof error === 'object'
      ? (error as ProductMutationError)
      : {};
  const rawMessage =
    typeof error === 'string' ? error : source.message || fallbackMessage;
  const searchable = [
    rawMessage,
    source.code,
    source.details,
    source.hint,
    source.constraint,
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();

  let code: string | undefined;
  let message: string | undefined;

  if (searchable.includes('product_edit_conflict')) {
    return {
      success: false,
      error: PRODUCT_EDIT_CONFLICT_MESSAGE,
      errorDetails: {
        code: 'PRODUCT_EDIT_CONFLICT',
        message: PRODUCT_EDIT_CONFLICT_MESSAGE,
        status: 409,
      },
      conflict: readProductEditSnapshot(source.details) ?? undefined,
    };
  }
  const methodCode = rawMessage.match(/\bPARCEL209_(?:PARCEL_SIZE_REQUIRED|INHERITED_METHOD|METHOD_INVALID|FAMILY_CHANGED_RETRY)\b/u)?.[0];
  if (methodCode) {
    code = methodCode;
    message = businessErrorMessage(methodCode);
  } else if (searchable.includes('product_edit_version_required')) {
    code = 'PRODUCT_EDIT_VERSION_REQUIRED';
    message = 'أعد فتح المنتج ثم احفظ التعديل.';
  } else if (
    searchable.includes('product_identifier_cross_collision') ||
    searchable.includes('نفس الرقم كـsku') ||
    searchable.includes('مستخدم بالفعل كـباركود') ||
    searchable.includes('مستخدم بالفعل كـ sku')
  ) {
    code = 'IDENTIFIER_COLLISION';
    message = 'لا يمكن استخدام نفس الرقم كـSKU لمنتج وباركود لمنتج آخر.';
  } else if (
    searchable.includes('products_barcode_normalized_key') ||
    searchable.includes('idx_products_barcode_unique') ||
    searchable.includes('الباركود مستخدم بالفعل')
  ) {
    code = 'DUPLICATE_BARCODE';
    message = 'الباركود مستخدم بالفعل لمنتج آخر.';
  } else if (
    searchable.includes('products_sku_normalized_key') ||
    searchable.includes('products_sku_key') ||
    searchable.includes('رمز الصنف sku مستخدم بالفعل')
  ) {
    code = 'DUPLICATE_SKU';
    message = 'رمز الصنف SKU مستخدم بالفعل لمنتج آخر.';
  } else if (
    source.code === '23505' ||
    searchable.includes('duplicate key value')
  ) {
    code = 'DUPLICATE_PRODUCT_IDENTIFIER';
    message = 'رمز SKU أو الباركود مستخدم بالفعل لمنتج آخر.';
  } else if (searchable.includes('المنتج الأساسي للنكهات') && searchable.includes('باركود')) {
    code = 'FLAVOR_MASTER_BARCODE_NOT_ALLOWED';
    message = 'المنتج الأساسي للنكهات للتجميع فقط ولا يحمل باركود بيع.';
  }

  if (message && code) {
    return {
      success: false,
      error: message,
      errorDetails: {
        code,
        message,
        status: readErrorStatus(error) || 409,
      },
    };
  }

  return {
    success: false,
    error: rawMessage,
    errorDetails: {
      code: source.code || 'RPC_ERROR',
      message: rawMessage,
      details: source.details || undefined,
      hint: source.hint || undefined,
      status: readErrorStatus(error) || 400,
    },
  };
}

