function isValidUuid(id?: string | null): boolean {
  if (!id) return false;
  return /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(id.trim());
}

export type AdminProductStatusFilter =
  | 'all'
  | 'healthy'
  | 'low_stock'
  | 'out_of_stock'
  | 'hidden';

export type AdminProductSort =
  | 'name'
