  };
}

const toFiniteNumber = (value: unknown): number => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
};

export function mapAdminProductRecord(record: Record<string, any>): Product {
  const onHandQuantity = toFiniteNumber(record.on_hand_quantity);
  const reservedQuantity = toFiniteNumber(record.reserved_quantity);
  const availableQuantity = Math.max(0, toFiniteNumber(record.available_quantity));
  const warehouseBalances = Array.isArray(record.warehouse_balances)
    ? record.warehouse_balances.map((balance: Record<string, unknown>) => ({
        warehouseId: String(balance.warehouse_id || ''),
        onHandQuantity: Math.max(0, toFiniteNumber(balance.on_hand_quantity)),
        reservedQuantity: Math.max(0, toFiniteNumber(balance.reserved_quantity)),
        availableQuantity: Math.max(0, toFiniteNumber(balance.available_quantity)),
      }))
    : [];
  const baseUnit = Array.isArray(record.base_unit) ? record.base_unit[0] : record.base_unit;
  const purchaseUnit = Array.isArray(record.purchase_unit) ? record.purchase_unit[0] : record.purchase_unit;
  const saleUnit = Array.isArray(record.sale_unit) ? record.sale_unit[0] : record.sale_unit;
  const costInJod = toFiniteNumber(record.cost_price_in_minor_units) / 1000;
  const saleInJod = toFiniteNumber(record.sale_price_in_minor_units) / 1000;
  const wholesaleInJod = toFiniteNumber(
    record.wholesale_price_in_minor_units ?? record.sale_price_in_minor_units,
  ) / 1000;
  const unitName = baseUnit?.name_ar || 'باكيت';
  const unitsPerPackage = Math.max(
    1,
    Math.floor(toFiniteNumber(record.units_per_purchase_unit) || 1),
  );
  const unitsPerSalePackage = Math.max(
    1,
    Math.floor(toFiniteNumber(record.units_per_sale_unit) || unitsPerPackage),
  );

  return {
    id: String(record.id || ''),
    sku: String(record.sku || ''),
    barcode: String(record.barcode || ''),
    nameAr: String(record.name_ar || ''),
    description: String(record.description || ''),
    imageUrl: String(record.image_url || ''),
    categoryId: String(record.category_id || ''),
    brandId: String(record.brand_id || ''),
    baseUnitId: baseUnit?.id || record.unit_id || undefined,
    baseUnitCode: baseUnit?.code || undefined,
    purchaseUnitId: purchaseUnit?.id || record.purchase_unit_id || undefined,
    purchaseUnitCode: purchaseUnit?.code || undefined,
    purchasePackage: purchaseUnit?.name_ar || unitName,
    unitsPerPackage,
    defaultPurchasePrice:
      toFiniteNumber(record.default_purchase_price_in_minor_units) / 1000 ||
      costInJod * unitsPerPackage,
    saleUnitId: saleUnit?.id || record.sale_unit_id || undefined,
    saleUnitCode: saleUnit?.code || undefined,
    salePackage: saleUnit?.name_ar || undefined,
    unitsPerSalePackage,
    parcelOnly: record.parcel_only === true,
    salePackagePrice: saleUnit
      ? toFiniteNumber(record.default_sale_price_in_minor_units) / 1000
      : 0,
    costPrice: costInJod,
    retailPrice: saleInJod,
    wholesalePrice: wholesaleInJod,
    taxRate: 16,
    unit: unitName,
    onHandQuantity,
    reservedQuantity,
    availableQuantity,
    reorderLevel: toFiniteNumber(record.min_stock_level),
    maxStockLevel:
      record.max_stock_level === null || record.max_stock_level === undefined
        ? undefined
        : toFiniteNumber(record.max_stock_level),
    warehouseId: record.warehouse_id || undefined,
    warehouseBalances,
    status: record.is_active
      ? availableQuantity === 0
        ? 'out_of_stock'
        : 'active'
      : 'hidden',
    createdAt: record.created_at || new Date().toISOString(),
    updatedAt: record.updated_at || new Date().toISOString(),
    isFlavorMaster: Boolean(record.is_flavor_master),
    flavorMasterProductId: record.flavor_master_product_id || undefined,
    flavorNameAr: record.flavor_name_ar || undefined,
    flavorSortOrder: toFiniteNumber(record.flavor_sort_order),
  };
}

const mapAdminProductRows = (value: unknown): Product[] =>
  Array.isArray(value)
    ? value.map((record) => mapAdminProductRecord(record))
    : [];

function requireProductClient() {
  if (!isSupabaseConfigured || !supabase) {
    throw new Error('إعدادات الاتصال بـ Supabase غير مكتملة.');
  }
  return supabase;
}

export async function fetchAdminProductPage(
  input: AdminProductPageInput = {},
): Promise<AdminProductPage> {
  const page = Math.max(1, Math.floor(input.page || 1));
  const pageSize = Math.min(100, Math.max(1, Math.floor(input.pageSize || 24)));
  const {data, error} = await requireProductClient().rpc('get_admin_product_page', {
    p_page: page,
    p_page_size: pageSize,
    p_search: input.search?.trim() || null,
    p_category_id: input.categoryId || null,
    p_status: input.status || 'all',
    p_sort: input.sort || 'name',
  });
  if (error) throw new Error(error.message || 'تعذر تحميل صفحة المنتجات.');

  const payload = data && typeof data === 'object'
    ? (data as Record<string, any>)
    : {};
  const metrics = payload.metrics && typeof payload.metrics === 'object'
    ? payload.metrics as Record<string, unknown>
    : {};
  const totalCount = Math.max(0, Math.floor(toFiniteNumber(payload.total_count)));

  return {
    products: mapAdminProductRows(payload.products),
    page,
    pageSize,
    totalCount,
    totalPages: Math.max(1, Math.ceil(totalCount / pageSize)),
    metrics: {
      lowStock: Math.max(0, Math.floor(toFiniteNumber(metrics.low_stock))),
      outOfStock: Math.max(0, Math.floor(toFiniteNumber(metrics.out_of_stock))),
      inventoryCost: toFiniteNumber(metrics.inventory_cost_in_minor_units) / 1000,
      potentialProfit: toFiniteNumber(metrics.potential_profit_in_minor_units) / 1000,
    },
  };
}

export async function searchAdminProducts(input: {
  search?: string;
  limit?: number;
  categoryId?: string;
  purpose?: AdminProductSearchPurpose;
  productId?: string;
} = {}): Promise<Product[]> {
  const limit = Math.min(50, Math.max(1, Math.floor(input.limit || 24)));
  const {data, error} = await requireProductClient().rpc('search_admin_products', {
    p_search: input.search?.trim() || null,
    p_limit: limit,
    p_category_id: input.categoryId || null,
    p_purpose: input.purpose || 'stockable',
    p_product_id: input.productId || null,
  });
  if (error) throw new Error(error.message || 'تعذر البحث في المنتجات.');
  return mapAdminProductRows(data);
}

export async function fetchAdminProductById(
  productId: string,
  purpose: AdminProductSearchPurpose = 'any',
): Promise<Product | null> {
  if (!isValidUuid(productId)) return null;
  const products = await searchAdminProducts({productId, purpose, limit: 1});
  return products[0] || null;
}

export async function fetchProductsFromSupabase(): Promise<{
  products: Product[];
  source: 'supabase';
  error?: string;
  errorDetails?: SupabaseFetchError;
  authSessionStatus?: 'authenticated' | 'unauthenticated' | 'error';
  authSessionUser?: string | null;
}> {
  if (!isSupabaseConfigured || !supabase) {
    return {
      products: [],
      source: 'supabase',
      error: 'لم يتم تعيين SUPABASE_URL و SUPABASE_PUBLISHABLE_KEY في src/config/supabase-public-config.ts',
    };
  }

  let authSessionStatus: 'authenticated' | 'unauthenticated' | 'error';
  let authSessionUser: string | null = null;

  try {
    const { data: sessionData, error: sessionErr } = await supabase.auth.getSession();
    if (sessionErr) {
      console.error('[Supabase Auth getSession Error]:', sessionErr);
      authSessionStatus = 'error';
    } else if (sessionData?.session?.user) {
      authSessionStatus = 'authenticated';
      authSessionUser = sessionData.session.user.email || sessionData.session.user.id;
    } else {
      authSessionStatus = 'unauthenticated';
    }
  } catch (err) {
    console.error('[Supabase Auth getSession Exception]:', err);
    authSessionStatus = 'error';
  }

  try {
    const { data, error: prodError } = await supabase.rpc(
      'search_admin_products',
      {
        p_search: null,
        p_limit: 50,
        p_category_id: null,
        p_purpose: 'any',
        p_product_id: null,
      },
    );
    const dbProducts = Array.isArray(data) ? data : [];

    if (prodError) {
      console.error('[Supabase fetchProducts Error]:', {
        message: prodError.message,
        code: prodError.code,
        status: readErrorStatus(prodError),
        details: prodError.details,
        hint: prodError.hint,
      });

      return {
        products: [],
        source: 'supabase',
        error: prodError.message,
        errorDetails: {
          message: prodError.message,
          code: prodError.code || 'UNKNOWN_CODE',
          status: readErrorStatus(prodError) || 400,
          details: prodError.details || undefined,
          hint: prodError.hint || undefined,
        },
        authSessionStatus,
        authSessionUser,
      };
    }

    if (!dbProducts || dbProducts.length === 0) {
      return {
        products: [],
        source: 'supabase',
        authSessionStatus,
        authSessionUser,
      };
    }

    const mappedProducts = mapAdminProductRows(dbProducts);

    return {
      products: mappedProducts,
      source: 'supabase',
      authSessionStatus,
      authSessionUser,
    };
  } catch (err: any) {
    console.error('[Supabase fetchProducts Exception]:', err);
    return {
      products: [],
      source: 'supabase',
      error: err?.message || String(err),
      errorDetails: {
        message: err?.message || String(err),
        code: 'CLIENT_EXCEPTION',
        status: 500,
      },
      authSessionStatus,
      authSessionUser,
    };
  }
}

/**
 * Creates a product with opening stock using RPC create_product_with_opening_stock
 */
export async function createProductWithOpeningStockInSupabase(
  input: CreateProductInput
): Promise<SupabaseRpcResult> {
  if (!isSupabaseConfigured || !supabase) {
    return {
      success: false,
      error: 'تكوين Supabase غير مكتمل في التطبيق.',
      errorDetails: {
        code: 'SUPABASE_NOT_CONFIGURED',
        message: 'تكوين Supabase غير مكتمل في التطبيق.',
      },
    };
  }

  // 1. Session Verification
  const { data: sessionData, error: sessionErr } = await supabase.auth.getSession();
  if (sessionErr || !sessionData?.session) {
    return {
      success: false,
      error: 'انتهت جلسة تسجيل الدخول، يرجى تسجيل الدخول مجددًا.',
      errorDetails: {
        code: 'AUTH_SESSION_EXPIRED',
        message: 'انتهت جلسة تسجيل الدخول، يرجى تسجيل الدخول مجددًا.',
        details: sessionErr?.message || 'لم يتم العثور على جلسة مصادقة نشطة في Supabase Client.',
        hint: 'يرجى تسجيل الخروج ثم إعادة تسجيل الدخول لتفعيل التوكن.',
      },
    };
  }

  // 2. Resolve UUIDs for relational parameters (warehouse_id, category_id, unit_id, brand_id)
  let warehouseIdToUse: string | null = isValidUuid(input.warehouseId) ? input.warehouseId! : null;
  if (!warehouseIdToUse) {
    const { data: whList } = await supabase.from('warehouses').select('id').eq('is_active', true).limit(1);
    if (whList && whList.length > 0) {
      warehouseIdToUse = whList[0].id;
    }
  }

  let categoryIdToUse: string | null = isValidUuid(input.categoryId) ? input.categoryId! : null;
  if (!categoryIdToUse) {
    const { data: catList } = await supabase.from('categories').select('id').eq('is_active', true).limit(1);
    if (catList && catList.length > 0) {
      categoryIdToUse = catList[0].id;
    }
  }

  let unitIdToUse: string | null = isValidUuid(input.unitId) ? input.unitId! : null;
  if (!unitIdToUse) {
    const { data: unitList } = await supabase.from('units').select('id').limit(1);
    if (unitList && unitList.length > 0) {
      unitIdToUse = unitList[0].id;
    }
  }

  let purchaseUnitIdToUse: string | null = null;
  if (input.purchasePackage?.trim()) {
    const { data: purchaseUnits } = await supabase
      .from('units')
      .select('id')
      .eq('name_ar', input.purchasePackage.trim())
      .limit(1);
    purchaseUnitIdToUse = purchaseUnits?.[0]?.id || null;
  }
  if (!purchaseUnitIdToUse) {
    purchaseUnitIdToUse = unitIdToUse;
  }

  let saleUnitIdToUse: string | null = null;
  if (input.salePackage?.trim()) {
    const { data: saleUnits } = await supabase
      .from('units')
      .select('id')
      .eq('name_ar', input.salePackage.trim())
      .limit(1);
    saleUnitIdToUse = saleUnits?.[0]?.id || null;
  }
  saleUnitIdToUse = saleUnitIdToUse || purchaseUnitIdToUse || unitIdToUse;

  const brandIdToUse: string | null = isValidUuid(input.brandId)
    ? input.brandId!
    : null;

  // 3. Convert prices to minor units (1 JOD = 1000 fils)
  const costMinorUnits = Math.round((Number(input.costPrice) || 0) * 1000);

  const rpcParams = {
    p_sku: input.sku.trim(),
    p_barcode: input.barcode ? input.barcode.trim() : null,
    p_name_ar: input.nameAr.trim(),
    p_description: input.description ? input.description.trim() : null,
    p_category_id: categoryIdToUse,
    p_brand_id: brandIdToUse,
    p_unit_id: unitIdToUse,
    p_purchase_unit_id: purchaseUnitIdToUse,
    p_units_per_purchase_unit: Math.max(
      1,
      Math.floor(Number(input.unitsPerPackage) || 1)
    ),
    p_default_purchase_price_in_minor_units: Math.round(
      Math.max(0, Number(input.defaultPurchasePrice) || 0) * 1000
    ),
    p_sale_unit_id: saleUnitIdToUse,
    p_units_per_sale_unit: Math.max(
      1,
      Math.floor(Number(input.unitsPerSalePackage) || 1)
    ),
    p_default_sale_price_in_minor_units: Math.round(
      Math.max(0, Number(input.salePackagePrice) || 0) * 1000
    ),
    p_cost_price_in_minor_units: costMinorUnits,
    p_min_stock_level: Number(input.reorderLevel) || 0,
    p_max_stock_level:
      input.maxStockLevel === undefined
        ? null
        : Number(input.maxStockLevel),
    p_warehouse_id: warehouseIdToUse,
    p_opening_quantity: 0,
    p_notes: 'تعريف منتج جديد برصيد صفر عبر التطبيق',
    p_image_url: input.imageUrl?.trim() || null,
  };

  try {
    const { data: res, error } = await supabase.rpc(
      'create_product_with_opening_stock_v5',
      {...rpcParams, p_parcel_only: input.parcelOnly ?? false}
    );

    if (error) {
      console.error(
        '[Supabase RPC Error] create_product_with_opening_stock_v4 failed:',
        error
      );
      return toProductMutationFailure(error, 'تعذر حفظ المنتج.');
    }

    const createdProdId = res?.product_id;

    if (!createdProdId) {
      return {
        success: false,
        error: 'لم يرجع الخادم معرف المنتج (product_id)',
        errorDetails: {
          code: 'MISSING_PRODUCT_ID',
          message: 'تم استدعاء الدالة لكن لم يتم إرجاع product_id.',
        },
      };
    }

    // Verify the canonical product row before reporting success to the UI.
    const { data: checkProd, error: checkProdErr } = await supabase
      .from('products')
      .select('id, name_ar, sku')
      .eq('id', createdProdId)
      .single();

    if (checkProdErr || !checkProd) {
      return {
        success: false,
        error: 'فشل التحقق من وجود السجل في public.products',
        errorDetails: {
          code: checkProdErr?.code || 'VERIFICATION_FAILED_PRODUCTS',
          message: checkProdErr?.message || 'لم يتواجد السجل في جدول public.products بعد إنشائه.',
          details: checkProdErr?.details,
          hint: checkProdErr?.hint,
        },
      };
    }

    return {
      success: true,
      productId: createdProdId,
      message: 'تم حفظ المنتج والمخزون في قاعدة البيانات بنجاح.',
    };
  } catch (err: any) {
    console.error('Exception during createProductWithOpeningStockInSupabase:', err);
    return toProductMutationFailure(err, 'تعذر الاتصال بـ Supabase');
  }
}

