export async function updateProductInSupabase(
  input: UpdateProductInput
): Promise<SupabaseRpcResult> {
  if (!isSupabaseConfigured || !supabase) {
    return {
      success: false,
      error: 'تكوين Supabase غير مكتمل في التطبيق.',
    };
  }

  try {
    let unitIdToUse = isValidUuid(input.unitId) ? input.unitId! : null;
    if (!unitIdToUse && input.unitName?.trim()) {
      const { data: units, error: unitError } = await supabase
        .from('units')
        .select('id')
        .eq('name_ar', input.unitName.trim())
        .limit(1);
      if (unitError) throw unitError;
      unitIdToUse = units?.[0]?.id || null;
    }

    let purchaseUnitIdToUse: string | null = null;
    if (input.purchasePackage?.trim()) {
      const { data: purchaseUnits, error: purchaseUnitError } = await supabase
        .from('units')
        .select('id')
        .eq('name_ar', input.purchasePackage.trim())
        .limit(1);
      if (purchaseUnitError) throw purchaseUnitError;
      purchaseUnitIdToUse = purchaseUnits?.[0]?.id || null;
    }
    purchaseUnitIdToUse = purchaseUnitIdToUse || unitIdToUse;

    let saleUnitIdToUse: string | null = null;
    if (input.salePackage?.trim()) {
      const { data: saleUnits, error: saleUnitError } = await supabase
        .from('units')
        .select('id')
        .eq('name_ar', input.salePackage.trim())
        .limit(1);
      if (saleUnitError) throw saleUnitError;
      saleUnitIdToUse = saleUnits?.[0]?.id || null;
    }
    saleUnitIdToUse =
      saleUnitIdToUse || purchaseUnitIdToUse || unitIdToUse;

    const { data, error } = await supabase.rpc('update_product_master_v5', {
      p_parcel_only: input.parcelOnly ?? null,
      p_product_id: input.productId,
      p_expected_updated_at: input.expectedUpdatedAt,
      p_sku: input.sku.trim(),
      p_barcode: input.barcode?.trim() || null,
      p_name_ar: input.nameAr.trim(),
      p_description: input.description?.trim() || null,
      p_category_id: isValidUuid(input.categoryId) ? input.categoryId : null,
      p_brand_id: isValidUuid(input.brandId) ? input.brandId : null,
      p_unit_id: unitIdToUse,
      p_purchase_unit_id: purchaseUnitIdToUse,
      p_units_per_purchase_unit: Math.max(
        1,
        Math.floor(Number(input.unitsPerPackage) || 1)
      ),
      p_default_purchase_price_in_minor_units: Math.round(
        Math.max(0, Number(input.defaultPurchasePrice) || 0) * 1000
      ),
      p_sale_unit_id: saleUnitIdToUse,
      p_units_per_sale_unit: Math.max(
        1,
        Math.floor(Number(input.unitsPerSalePackage) || 1)
      ),
      p_default_sale_price_in_minor_units: Math.round(
        Math.max(0, Number(input.salePackagePrice) || 0) * 1000
      ),
      p_cost_price_in_minor_units: Math.round(
        Math.max(0, Number(input.costPrice) || 0) * 1000
      ),
      p_min_stock_level: Math.max(
        0,
        Math.floor(Number(input.reorderLevel) || 0)
      ),
      p_max_stock_level:
        input.maxStockLevel === undefined
          ? null
          : Math.max(0, Math.floor(Number(input.maxStockLevel) || 0)),
      p_is_active: input.isActive,
      p_image_url: input.imageUrl?.trim() || null,
    });

    if (error) {
      return toProductMutationFailure(error, 'تعذر تحديث المنتج.');
    }

    return {
      success: Boolean(data?.success),
      productId: data?.productId || input.productId,
      message: data?.message || 'تم تحديث المنتج بنجاح.',
      updatedAt: data?.updatedAt,
    };
  } catch (error: any) {
    return toProductMutationFailure(
      error,
      'تعذر تحديث المنتج في Supabase.'
    );
  }
}

src/stores/useAppStore.ts.beforeText:
import {requestScreenNavigation} from '../utils/screenHistory';
/**
 * Nawasrah Business Manager - Global Application Store & State Engine
 */

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  useSyncExternalStore,
} from 'react';
import {
  AuditLog,
  Branch,
  Brand,
  Category,
  Customer,
  CustomerPayment,
  Expense,
  InventoryMovement,
  MovementType,
  Invoice,
  NotificationItem,
  Order,
  OrderItem,
  OrderStatus,
  PaymentMethod,
  Product,
  Shift,
  Supplier,
  SupplierPayment,
  UnitDefinition,
  User,
  Warehouse,
  Account,
  JournalEntry,
} from '../types';
import {
  ROLE_PERMISSIONS_MAP,
} from '../constants';
import { isSupabaseConfigured, sanitizedSupabaseUrl, sanitizedSupabaseKey, isValidSupabaseUrl } from '../lib/supabase';
import {
  fetchProductsFromSupabase,
  createProductWithOpeningStockInSupabase,
  updateProductInSupabase,
  type SupabaseRpcResult,
} from '../services/supabase/products.service';
import {
  adjustInventoryStockInSupabase,
  fetchInventoryMovementsFromSupabase,
  type InventoryMovementPageInput,
  type InventoryMovementPage,
  transferInventoryBetweenWarehousesInSupabase,
} from '../services/supabase/inventory.service';
import {
  fetchCategoriesFromSupabase,
  fetchBrandsFromSupabase,
  fetchUnitsFromSupabase,
  fetchBranchesFromSupabase,
  fetchWarehousesFromSupabase,
} from '../services/supabase/reference-data.service';
import {
  fetchOperationalOrdersSummaryFromSupabase,
  confirmOrderInSupabase,
  completeWebsiteOrderWithPaymentInSupabase,
  completeWebsiteOrderWithSettlementInSupabase,
  cancelOrderInSupabase,
  returnCompletedWebsiteOrderInSupabase,
  startOrUpdateOrderDeliveryInSupabase,
  updateOrderStatusInSupabase,
} from '../services/supabase/orders.service';
import {
  createPosSaleInSupabase,
  getOrCreatePublicPosReceiptUrlFromSupabase,
} from '../services/supabase/pos.service';
import {
  hasRegisteredDeviceBiometric,
  registerDeviceBiometric,
  removeRegisteredDeviceBiometric,
  verifyDeviceBiometric,
} from '../services/deviceBiometrics.service';
import {
  cancelEmptyCashShiftInSupabase,
  closeCashShiftInSupabase,
  createOperationalExpenseInSupabase,
  fetchExpenseShiftCenterFromSupabase,
  openCashShiftInSupabase,
  reverseOperationalExpenseInSupabase,
  reverseCashShiftWithOperationsInSupabase,
} from '../services/supabase/expenses-shifts.service';
import {
  type SelectorCache,
  type SelectorEquality,
  updateSelectorCache,
} from './storeSelectors';
import {
  type ActiveTab,
  type ThemeMode,
  loadPersistedAppPreferences,
  serializeAppPreferences,
  writePersistedAppPreferences,
} from './appStorePreferences';
import { ReferenceDataStoreSlice } from './referenceData.storeSlice';
import { StockNotificationsStoreSlice } from './stockNotifications.storeSlice';
import {
  type ModalName,
  type ModalOpenArguments,
  type ModalPayload,
  type OpenModal,
} from './modalTypes';

export { shallowEqual } from './storeSelectors';

const UNAUTHENTICATED_USER: User = {
  id: '',
  name: 'مستخدم غير مسجل',
  email: '',
  phone: '',
  role: 'View Only',
  branchId: '',
  themeMode: 'dark',
  permissions: [],
  isActive: false,
};

const LOADING_BRANCH: Branch = {
  id: '',
  name: 'جاري تحميل الفرع',
  address: '',
  city: '',
  phone: '',
  isMain: false,
};

export interface SupabaseDiagnosticInfo {
  hasUrl: boolean;
  isValidUrlScheme: boolean;
  hasKey: boolean;
  isConfigured: boolean;
  authSessionStatus: 'authenticated' | 'unauthenticated' | 'error' | 'checking';
  authSessionUser?: string | null;
  productsQueryStatus: 'success' | 'failed' | 'idle' | 'loading';
  productsErrorCode?: string;
  productsErrorMessage?: string;
  productsErrorStatus?: number | string;
  productsErrorDetails?: string;
  productsErrorHint?: string;
}

export interface AppState {
  // Auth & Session
  currentUser: User;
  users: User[];
  activeBranch: Branch;
  branches: Branch[];
  warehouses: Warehouse[];
  isBiometricsEnabled: boolean;
  isLockedWithFaceId: boolean;

  // Domain Collections
  products: Product[];
  categories: Category[];
  brands: Brand[];
  units: UnitDefinition[];
  orders: Order[];
  newOrdersCount: number;
  invoices: Invoice[];
  customers: Customer[];
  suppliers: Supplier[];
  expenses: Expense[];
  currentShift: Shift | null;
  recentShifts: Shift[];
  movements: InventoryMovement[];
  movementPage: Omit<InventoryMovementPage, 'movements'> & {
    productId: string | null;
  };
  accounts: Account[];
  journalEntries: JournalEntry[];
  customerPayments: CustomerPayment[];
  supplierPayments: SupplierPayment[];
  notifications: NotificationItem[];
  auditLogs: AuditLog[];

  // App UI State
  isQuickActionOpen: boolean;
  activeTab: ActiveTab;
  currentModal: ModalName | null;
  modalData: ModalPayload;
  customerNavigationTarget: string | null;
  toast: { message: string; type: 'success' | 'error' | 'info' } | null;

  isProductsLoading: boolean;
  productsSource: 'supabase';
  productsError: string | null;
  productDataRevision: number;
  supabaseDiagnostics: SupabaseDiagnosticInfo;
}

class StoreEngine {
  private state: AppState;
  private listeners: Set<() => void> = new Set();
  private persistedPreferencesSnapshot: string | null = null;
  private productsRefreshPromise: Promise<void> | null = null;
  private ordersRefreshPromise: Promise<void> | null = null;
  private movementsRefreshRequestId = 0;
  private financeRefreshPromise: Promise<void> | null = null;
  private readonly referenceDataSlice: ReferenceDataStoreSlice;
  private readonly stockNotificationsSlice: StockNotificationsStoreSlice;

  constructor() {
    const initial = this.getInitialState();
    const preferences = loadPersistedAppPreferences();

    this.state = {
      ...initial,
      activeTab: preferences.activeTab ?? initial.activeTab,
      currentModal: null,
      currentUser: {
        ...UNAUTHENTICATED_USER,
        themeMode: preferences.themeMode ?? initial.currentUser.themeMode,
      },
      isQuickActionOpen: false,
      isBiometricsEnabled: false,
      isLockedWithFaceId: false,
    };

    this.referenceDataSlice = new ReferenceDataStoreSlice({
      getCategories: () => this.state.categories,
      getBrands: () => this.state.brands,
      getUnits: () => this.state.units,
      replaceCategories: (categories) => {
        this.state.categories = categories;
        this.notify();
      },
      replaceBrands: (brands) => {
        this.state.brands = brands;
        this.notify();
      },
      replaceUnits: (units) => {
        this.state.units = units;
        this.notify();
      },
      setToast: (message, type) => this.setToast(message, type),
    });
    this.stockNotificationsSlice = new StockNotificationsStoreSlice({
      isConfigured: () => isSupabaseConfigured,
      getNotifications: () => this.state.notifications,
      replaceNotifications: (notifications) => {
        this.state.notifications = notifications;
      },
      notify: () => this.notify(),
      setToast: (message, type) => this.setToast(message, type),
    });

    // Rewrite any legacy full-state payload as compact UI-only preferences.
    this.persistUiPreferences();
  }

  public refreshOrdersFromSupabase(): Promise<void> {
    if (this.ordersRefreshPromise) return this.ordersRefreshPromise;

    const refreshPromise = this.performOrdersRefresh().finally(() => {
      if (this.ordersRefreshPromise === refreshPromise) {
        this.ordersRefreshPromise = null;
      }
    });
    this.ordersRefreshPromise = refreshPromise;
    return refreshPromise;
  }

  private async performOrdersRefresh(): Promise<void> {
    if (!isSupabaseConfigured) return;
    try {
      const res = await fetchOperationalOrdersSummaryFromSupabase();
      if (res.success) {
        this.state.newOrdersCount = res.summary.review;
        this.notify();
      }
    } catch (err) {
      console.error('[Store refreshOrdersFromSupabase Exception]:', err);
    }
  }

  public refreshProductsFromSupabase(): Promise<void> {
    if (this.productsRefreshPromise) return this.productsRefreshPromise;

    const refreshPromise = this.performProductsRefresh().finally(() => {
      if (this.productsRefreshPromise === refreshPromise) {
        this.productsRefreshPromise = null;
      }
    });
    this.productsRefreshPromise = refreshPromise;
    return refreshPromise;
  }

  public cacheProductPage(products: Product[]) {
    const bounded = new Map<string, Product>();
    [...products, ...this.state.products].forEach((product) => {
      if (!bounded.has(product.id) && bounded.size < 150) {
        bounded.set(product.id, product);
      }
    });
    this.state.products = [...bounded.values()];
    this.notify();
  }

  public async refreshReferenceDataFromSupabase(): Promise<void> {
    if (!isSupabaseConfigured) return;
    const [categories, brands, units, branches, warehouses] = await Promise.all([
      fetchCategoriesFromSupabase(),
      fetchBrandsFromSupabase(),
      fetchUnitsFromSupabase(),
      fetchBranchesFromSupabase(),
      fetchWarehousesFromSupabase(),
    ]);

    this.state.categories = categories;
    this.state.brands = brands;
    this.state.units = units;
    this.state.branches = branches;
    if (branches.length > 0) {
      this.state.activeBranch =
        branches.find((branch) => branch.id === this.state.activeBranch?.id) ??
        branches[0];
    }
    this.state.warehouses = warehouses;
    this.notify();

    if (this.state.currentUser.id && this.state.activeBranch.id) {
      try {
        await this.refreshExpenseShiftCenterFromSupabase();
      } catch (error) {
        console.warn('[Store finance center refresh skipped]:', error);
      }
    }
  }

  private async performProductsRefresh(): Promise<void> {
    this.state.isProductsLoading = true;
    this.state.supabaseDiagnostics = {
      ...this.state.supabaseDiagnostics,
      productsQueryStatus: 'loading',
    };
    this.notify();

    try {
      const res = await fetchProductsFromSupabase();
      this.state.products = res.products;
      this.state.productDataRevision += 1;
      this.state.productsSource = res.source;
      this.state.productsError = res.error || null;

      this.state.supabaseDiagnostics = {
        hasUrl: Boolean(sanitizedSupabaseUrl),
        isValidUrlScheme: isValidSupabaseUrl,
        hasKey: Boolean(sanitizedSupabaseKey),
        isConfigured: isSupabaseConfigured,
        authSessionStatus: res.authSessionStatus || 'unauthenticated',
        authSessionUser: res.authSessionUser,
        productsQueryStatus: res.errorDetails ? 'failed' : 'success',
        productsErrorCode: res.errorDetails?.code,
        productsErrorMessage: res.errorDetails?.message,
        productsErrorStatus: res.errorDetails?.status,
        productsErrorDetails: res.errorDetails?.details,
        productsErrorHint: res.errorDetails?.hint,
      };

      if (res.source === 'supabase') {
        if (!res.errorDetails) {
          await this.refreshReferenceDataFromSupabase();
        }
      }
    } catch (err: unknown) {
      const errorMessage = err instanceof Error ? err.message : String(err);
      console.error('[Store refreshProductsFromSupabase Exception]:', err);
      this.state.productsSource = 'supabase';
      this.state.productsError = errorMessage || 'تعذر الاتصال بـ Supabase';
      this.state.supabaseDiagnostics = {
        ...this.state.supabaseDiagnostics,
        productsQueryStatus: 'failed',
        productsErrorMessage: errorMessage,
      };
    } finally {
      this.state.isProductsLoading = false;
      this.notify();
    }
  }

  public refreshCategoriesFromSupabase() {
    return this.referenceDataSlice.refreshCategories();
  }

  public refreshBrandsFromSupabase() {
    return this.referenceDataSlice.refreshBrands();
  }

  public refreshUnitsFromSupabase() {
    return this.referenceDataSlice.refreshUnits();
  }

  public async refreshInventoryMovementsFromSupabase(
    input: InventoryMovementPageInput = {}
  ): Promise<void> {
    if (!isSupabaseConfigured) return;

    const requestId = ++this.movementsRefreshRequestId;

    try {
      const result = await fetchInventoryMovementsFromSupabase(input);
      if (requestId !== this.movementsRefreshRequestId) return;
      this.state.movements = result.movements;
      this.state.movementPage = {
        page: result.page,
        pageSize: result.pageSize,
        totalCount: result.totalCount,
        totalPages: result.totalPages,
        productMovementCounts: result.productMovementCounts,
        salesProductIds: result.salesProductIds,
        productId: input.productId ?? null,
      };
      this.notify();
    } catch (error) {
      console.error(
        '[Store refreshInventoryMovements Exception]:',
        error
      );
    }
  }

  public refreshExpenseShiftCenterFromSupabase(): Promise<void> {
    if (this.financeRefreshPromise) return this.financeRefreshPromise;

    const refreshPromise = this.performFinanceRefresh().finally(() => {
      if (this.financeRefreshPromise === refreshPromise) {
        this.financeRefreshPromise = null;
      }
    });
    this.financeRefreshPromise = refreshPromise;
    return refreshPromise;
  }

  private async performFinanceRefresh(): Promise<void> {
    if (
      !isSupabaseConfigured ||
      !this.state.currentUser.id ||
      !this.state.activeBranch.id
    ) {
      return;
    }

    try {
      const center = await fetchExpenseShiftCenterFromSupabase(
        this.state.activeBranch.id
      );
      this.state.expenses = center.expenses;
      this.state.currentShift = center.currentShift;
      this.state.recentShifts = center.recentShifts;
      this.notify();
    } catch (error) {
      console.error('[Store refreshExpenseShiftCenter Exception]:', error);
      throw error;
    }
  }

  public refreshStockNotificationsFromSupabase(): Promise<NotificationItem[]> {
    return this.stockNotificationsSlice.refresh();
  }

  public markNotificationRead(notificationId: string) {
    return this.stockNotificationsSlice.markRead(notificationId);
  }

  public markAllNotificationsRead() {
    return this.stockNotificationsSlice.markAllRead();
  }

  private getInitialState(): AppState {
    return {
      currentUser: UNAUTHENTICATED_USER,
      users: [],
      activeBranch: LOADING_BRANCH,
      branches: [],
      warehouses: [],
      isBiometricsEnabled: false,
      isLockedWithFaceId: false,

      products: [],
      categories: [],
      brands: [],
      units: [],
      orders: [],
      newOrdersCount: 0,
      invoices: [],
      customers: [],
      suppliers: [],
      expenses: [],
      currentShift: null,
      recentShifts: [],
      movements: [],
      movementPage: {
        page: 1,
        pageSize: 25,
        totalCount: 0,
        totalPages: 1,
        productMovementCounts: {},
        salesProductIds: [],
        productId: null,
      },
      accounts: [],
      journalEntries: [],
      customerPayments: [],
      supplierPayments: [],
      notifications: [],
      auditLogs: [],

      isQuickActionOpen: false,
      activeTab: 'home',
      currentModal: null,
      modalData: null,
      customerNavigationTarget: null,
      toast: null,
      isProductsLoading: false,
      productsSource: 'supabase',
      productsError: null,
      productDataRevision: 0,
      supabaseDiagnostics: {
        hasUrl: Boolean(sanitizedSupabaseUrl),
        isValidUrlScheme: isValidSupabaseUrl,
        hasKey: Boolean(sanitizedSupabaseKey),
        isConfigured: isSupabaseConfigured,
        authSessionStatus: 'checking',
        productsQueryStatus: 'idle',
      },
    };
  }

  public getState(): AppState {
    return this.state;
  }

  public subscribe(listener: () => void) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  private notify() {
    this.persistUiPreferences();
    this.listeners.forEach((listener) => {
      try {
        listener();
      } catch (error) {
        console.error('[Store listener error]:', error);
      }
    });
  }

  private persistUiPreferences() {
    const serializedPreferences = serializeAppPreferences(
      this.state.activeTab,
      this.state.currentUser.themeMode === 'light' ? 'light' : 'dark'
    );

    if (serializedPreferences === this.persistedPreferencesSnapshot) return;

    if (writePersistedAppPreferences(serializedPreferences)) {
      this.persistedPreferencesSnapshot = serializedPreferences;
    }
  }

  // --- Actions ---

  public setToast(
    message: string | { message?: string; type?: 'success' | 'error' | 'info' },
    type: 'success' | 'error' | 'info' = 'success'
  ) {
    let finalMsg: string;
    let finalType = type;

    if (typeof message === 'object' && message !== null) {
      finalMsg = message.message || JSON.stringify(message);
      if (message.type) {
        finalType = message.type;
      }
    } else {
      finalMsg = String(message || '');
    }

    this.state.toast = { message: finalMsg, type: finalType };
    this.notify();
    setTimeout(() => {
      this.state.toast = null;
      this.notify();
    }, 3500);
  }

  public setActiveTab(tab: AppState['activeTab']) {
    if (!requestScreenNavigation(tab)) return;
    this.state.activeTab = tab;
    this.notify();
  }

  public openCustomerProfile(customerId: string) {
    if (!requestScreenNavigation('accounts')) return;
    this.state.currentModal = null;
    this.state.modalData = null;
    this.state.customerNavigationTarget = customerId;
    this.state.activeTab = 'accounts';
    this.notify();
  }

  public clearCustomerNavigationTarget() {
    if (!this.state.customerNavigationTarget) return;
    this.state.customerNavigationTarget = null;
    this.notify();
  }

  public toggleQuickAction(open?: boolean) {
    this.state.isQuickActionOpen = open ?? !this.state.isQuickActionOpen;
    this.notify();
  }

  public readonly openModal: OpenModal = (
    ...[modalName, data]: ModalOpenArguments
  ) => {
    this.state.currentModal = modalName;
    this.state.modalData = data ?? null;
    this.notify();
  };

  public closeModal() {
    this.state.currentModal = null;
    this.state.modalData = null;
    this.notify();
  }

  public setActiveBranch(branchId: string) {
    const branch = this.state.branches.find((b) => b.id === branchId);
    if (branch) {
      this.state.activeBranch = branch;
      this.state.currentUser.branchId = branchId;
      this.addAuditLog('تغيير الفرع', `تم الانتقال إلى ${branch.name}`);
      this.setToast(`تم الانتقال إلى ${branch.name}`);
      this.notify();
      void this.refreshExpenseShiftCenterFromSupabase().catch(() => undefined);
    }
  }

  public setCurrentUser(userUpdates: Partial<User>) {
    const previousUserId = this.state.currentUser.id;
    this.state.currentUser = {
      ...this.state.currentUser,
      ...userUpdates,
      permissions: userUpdates.role
        ? ROLE_PERMISSIONS_MAP[userUpdates.role] || this.state.currentUser.permissions
        : this.state.currentUser.permissions,
    };

    if (userUpdates.id && userUpdates.id !== previousUserId) {
      this.state.isBiometricsEnabled = hasRegisteredDeviceBiometric(
        userUpdates.id
      );
      this.state.isLockedWithFaceId = false;
    }

    this.notify();
  }

  public async toggleBiometrics() {
    const { id, name } = this.state.currentUser;

    if (this.state.isBiometricsEnabled) {
      removeRegisteredDeviceBiometric(id);
      this.state.isBiometricsEnabled = false;
      this.state.isLockedWithFaceId = false;
      this.addAuditLog(
        'تعطيل بصمة الجهاز',
        'تم تعطيل قفل التطبيق ببصمة الجهاز على هذا الجهاز'
      );
      this.setToast('تم إيقاف قفل Face ID على هذا الجهاز.');
      this.notify();
      return true;
    }

    const result = await registerDeviceBiometric(id, name);
    if (!result.success) {
      this.setToast(result.error || 'تعذر تفعيل بصمة الجهاز.', 'error');
      return false;
    }

    this.state.isBiometricsEnabled = true;
    this.state.isLockedWithFaceId = false;
    this.addAuditLog(
      'تفعيل بصمة الجهاز',
      'تم تسجيل بصمة الجهاز وتفعيل قفل التطبيق'
    );
    this.setToast('تم تفعيل Face ID والتحقق من بصمة الجهاز بنجاح.');
    this.notify();
    return true;
  }

  public lockWithFaceId() {
    if (
      !this.state.isBiometricsEnabled ||
      !hasRegisteredDeviceBiometric(this.state.currentUser.id)
    ) {
      return false;
    }

    this.state.isLockedWithFaceId = true;
    this.notify();
    return true;
  }

  public async unlockFaceId() {
    if (!this.state.isBiometricsEnabled) {
      this.state.isLockedWithFaceId = false;
      this.notify();
      return true;
    }

    const result = await verifyDeviceBiometric(this.state.currentUser.id);
    if (!result.success) {
      this.setToast(result.error || 'تعذر التحقق من بصمة الجهاز.', 'error');
      return false;
    }

    this.state.isLockedWithFaceId = false;
    this.setToast('تم التأكد من الهوية بواسطة بصمة الجهاز.');
    this.notify();
    return true;
  }

  public clearFaceIdLockForPasswordSignIn() {
    this.state.isLockedWithFaceId = false;
    this.notify();
  }

  private addAuditLog(action: string, details: string) {
    const newLog: AuditLog = {
      id: `log-${Date.now()}`,
      timestamp: new Date().toISOString(),
      userId: this.state.currentUser.id,
      userName: this.state.currentUser.name,
      action,
      details,
    };
    this.state.auditLogs = [newLog, ...this.state.auditLogs];
  }

  // --- Atomic Stock & Order Actions ---

  public async confirmOrder(orderId: string, notes?: string) {
    if (isSupabaseConfigured) {
      const res = await confirmOrderInSupabase(orderId, notes);
      if (!res.success) {
        this.setToast(`فشل تأكيد الطلب: ${res.error}`, 'error');
        return;
      }
      this.setToast(res.message || 'تم قبول الطلب وحجز المخزون بنجاح');
      await this.refreshOrdersFromSupabase();
      await this.refreshProductsFromSupabase();
      return;
    }

    const order = this.state.orders.find((o) => o.id === orderId);
    if (!order) return;

    if (order.status !== 'new' && order.status !== 'pending_confirmation') {
      this.setToast('هذا الطلب غير مؤهل للتأكيد الفوري', 'error');
      return;
    }

    // Atomic check: Verify available quantities for all items
    for (const item of order.items) {
      const prod = this.state.products.find((p) => p.id === item.productId);
      if (!prod) {
        this.setToast(`المنتج ${item.productName} غير موجود بالمخزون!`, 'error');
        return;
      }
      if (prod.availableQuantity < item.quantity) {
        this.setToast(
          `تعارض مخزون: الكمية المتاحة من ${prod.nameAr} هي ${prod.availableQuantity} فقط بينما المطلوب ${item.quantity}!`,
          'error'
        );
        return;
      }
    }

    // Perform atomic reservation
    order.items.forEach((item) => {
      const prod = this.state.products.find((p) => p.id === item.productId);
      if (prod) {
        const prevQty = prod.onHandQuantity;
        prod.reservedQuantity += item.quantity;
        prod.availableQuantity = prod.onHandQuantity - prod.reservedQuantity;

        // Record inventory movement: Reservation
        this.state.movements.unshift({
          id: `mov-${Date.now()}-${Math.random()}`,
          productId: prod.id,
          productName: prod.nameAr,
          branchId: this.state.activeBranch.id,
          warehouseId: 'w-main',
          movementType: 'Reservation',
          previousQuantity: prevQty,
          quantityChange: item.quantity,
          newQuantity: prod.availableQuantity,
          reason: `حجز كمية للطلب رقم ${order.orderNumber}`,
          performedByUserId: this.state.currentUser.id,
          performedByUserName: this.state.currentUser.name,
          timestamp: new Date().toISOString(),
          referenceId: order.id,
        });
      }
    });

    order.status = 'confirmed';
    order.isNew = false;
    order.statusHistory.push({
      status: 'confirmed',
      changedAt: new Date().toISOString(),
      changedBy: this.state.currentUser.name,
    });

    this.addAuditLog('تأكيد طلب زبائن', `تم تأكيد وحجز كميات الطلب ${order.orderNumber}`);
    this.setToast(`تم قبول الطلب ${order.orderNumber} وحجز المنتجات بنجاح`);
    this.notify();
  }

  public async cancelOrder(orderId: string, reason: string = 'إلغاء بواسطة الإدارة') {
    if (isSupabaseConfigured) {
      const res = await cancelOrderInSupabase(orderId, reason);
      if (!res.success) {
        this.setToast(`فشل إلغاء الطلب: ${res.error}`, 'error');
        return;
      }
      this.setToast(res.message || 'تم إلغاء الطلب وتحرير الكميات المحجوزة');
      await this.refreshOrdersFromSupabase();
      await this.refreshProductsFromSupabase();
      return;
    }

    const order = this.state.orders.find((o) => o.id === orderId);
    if (!order) return;

    // Release reservation if it was confirmed or processing
    if (order.status === 'confirmed' || order.status === 'processing') {
      order.items.forEach((item) => {
        const prod = this.state.products.find((p) => p.id === item.productId);
        if (prod) {
          prod.reservedQuantity = Math.max(0, prod.reservedQuantity - item.quantity);
          prod.availableQuantity = prod.onHandQuantity - prod.reservedQuantity;

          this.state.movements.unshift({
            id: `mov-${Date.now()}-${Math.random()}`,
            productId: prod.id,
            productName: prod.nameAr,
            branchId: this.state.activeBranch.id,
            warehouseId: 'w-main',
            movementType: 'Release Reservation',
            previousQuantity: prod.onHandQuantity,
            quantityChange: -item.quantity,
            newQuantity: prod.availableQuantity,
            reason: `تحرير حجز بسبب إلغاء الطلب ${order.orderNumber}: ${reason}`,
            performedByUserId: this.state.currentUser.id,
            performedByUserName: this.state.currentUser.name,
            timestamp: new Date().toISOString(),
            referenceId: order.id,
          });
        }
      });
    }

    order.status = 'cancelled';
    order.isNew = false;
    order.statusHistory.push({
      status: 'cancelled',
      changedAt: new Date().toISOString(),
      changedBy: this.state.currentUser.name,
      reason,
    });

    this.addAuditLog('إلغاء طلب', `تم إلغاء الطلب ${order.orderNumber}`);
    this.setToast(`تم إلغاء الطلب ${order.orderNumber} وتحرير الكميات المحجوزة`);
    this.notify();
  }

